const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<title>DTL War Room</title>\n<style>:root{--bg:#000;--panel:#050505;--panel2:#0a0a0a;--line:#292929;--text:#fff;--muted:#a7a7a7;--good:#fff;--warn:#d7d7d7;--bad:#bdbdbd;--accent:#fff}*{box-sizing:border-box}body{margin:0;background:#000;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}.shell{max-width:1500px;margin:auto;padding:28px}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.3em;color:#aaa;font-weight:900}.topbar h1{margin:2px 0 0;font-size:28px;letter-spacing:.06em}.brand-lockup{display:flex;align-items:center;gap:12px}.dtl-mark{width:48px;height:48px;border:2px solid #fff;border-radius:12px;display:grid;place-items:center;background:#fff;color:#000;font-size:16px;font-weight:1000;letter-spacing:-.04em}.brand-copy{min-width:0}.brand-sub{font-size:9px;color:#888;letter-spacing:.16em;margin-top:3px;font-weight:800}.live{border:1px solid var(--line);background:#050505;border-radius:999px;padding:10px 14px;font-size:11px;font-weight:800;letter-spacing:.12em}.live span{display:inline-block;width:8px;height:8px;background:var(--good);border-radius:50%;margin-right:8px;box-shadow:0 0 14px var(--good)}.platform-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#050505;border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 14px 50px #0007}.platform-head,.row{display:flex;justify-content:space-between;gap:12px;align-items:center}.platform-name{font-size:18px;font-weight:900}.handle,.muted{color:var(--muted);font-size:12px}.big{font-size:28px;font-weight:900;margin:16px 0 4px}.progress{height:9px;background:#202020;border-radius:999px;overflow:hidden;margin:8px 0}.progress i{display:block;height:100%;background:#fff;border-radius:999px}.metric{margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}.data-missing{color:var(--warn);font-weight:800;font-size:12px}.tabs{display:flex;gap:8px;overflow:auto;margin:20px 0 14px;padding-bottom:4px}.tabs button{border:1px solid var(--line);background:#050505;color:var(--muted);border-radius:999px;padding:10px 14px;font-size:11px;font-weight:900;letter-spacing:.08em;white-space:nowrap;cursor:pointer}.tabs button.active{color:#000;background:var(--good);border-color:var(--good)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.span8{grid-column:span 8}.span4{grid-column:span 4}.span6{grid-column:span 6}.section-title{font-size:12px;letter-spacing:.13em;color:var(--muted);font-weight:900;margin-bottom:14px}.agent-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.agent{padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--panel);min-width:0}.avatar{width:46px;height:46px;border-radius:50%;background:#000;border:1px solid #3a3a3a;display:grid;place-items:center;font-weight:900;margin-bottom:12px}.agent h3{font-size:13px;margin:0 0 4px}.agent p{font-size:12px;color:var(--muted);line-height:1.5;margin:8px 0}.status{font-size:10px;color:var(--good);font-weight:900;letter-spacing:.1em}.current-task{margin:14px 0 10px;padding:12px;border:1px solid #2b2b2b;border-radius:13px;background:#090909}.task-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:9px}.task-label{font-size:9px;font-weight:1000;letter-spacing:.14em;color:var(--good)}.task-type{font-size:8px;font-weight:900;letter-spacing:.08em;border:1px solid #444;border-radius:999px;padding:4px 7px;color:#ddd;white-space:nowrap}.task-target{font-size:13px;font-weight:900;line-height:1.28;color:#fff;overflow-wrap:anywhere}.task-meta{font-size:10px;color:var(--good);margin-top:5px;line-height:1.35}.task-detail{font-size:11px;color:var(--muted);margin-top:7px;line-height:1.42}.task-time{font-size:9px;color:#707070;margin-top:8px}.agent-top{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.agent-top .avatar{margin-bottom:0}.agent-id{flex:1;min-width:0}.finding{padding-top:9px;border-top:1px solid var(--line)}.activity-item{padding:12px 0;border-bottom:1px solid var(--line);font-size:13px}.activity-item b{color:var(--good);font-size:11px;margin-right:8px}.meeting-stage{min-height:580px;position:relative;background:#030303;border:1px solid var(--line);border-radius:22px;overflow:hidden;padding:30px}.table-core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:260px;height:150px;border:1px solid #3a3a3a;border-radius:50%;background:#080808;display:grid;place-items:center;text-align:center}.meeting-agent{position:absolute;width:190px}.meeting-agent .bubble{background:#0b0b0b;border:1px solid #303030;border-radius:14px;padding:10px;font-size:11px;line-height:1.4;color:#ddd;margin-top:7px}.meeting-agent .avatar{margin:0}.decision-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-top:14px}.decision{border:1px solid var(--line);border-radius:14px;padding:14px;background:#080808}.decision b{display:block;font-size:10px;color:var(--good);letter-spacing:.1em;margin-bottom:7px}.opp{display:grid;grid-template-columns:1.3fr .7fr .7fr .8fr;gap:12px;padding:16px 0;border-bottom:1px solid var(--line);align-items:start}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:9px;font-weight:900;letter-spacing:.08em}.fit{font-size:22px;font-weight:900;color:var(--good)}.pitch{white-space:pre-wrap;background:#030303;border:1px solid var(--line);padding:14px;border-radius:12px;color:#ccc;font-size:12px;line-height:1.55;margin-top:10px}.post-now{padding:14px;border:1px solid var(--line);border-radius:14px;margin-bottom:10px}.post-now b{color:var(--good)}.headline{font-size:32px;max-width:800px;line-height:1.08;margin:8px 0 22px}.scanner{margin:16px 0 18px;padding:15px;border:1px solid #2b2b2b;border-radius:14px;background:#070707}.scanner-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-top:12px}.scanner-stat{padding:10px;border:1px solid var(--line);border-radius:12px;background:#050505}.scanner-stat b{display:block;font-size:16px;margin-top:3px}.scan-live{color:var(--good);font-weight:900;letter-spacing:.08em}.scan-btn{border:1px solid var(--good);background:var(--good);color:#000;border-radius:999px;padding:9px 13px;font-size:10px;font-weight:1000;letter-spacing:.08em;cursor:pointer}.scan-btn:disabled{opacity:.45;cursor:wait}.source-link{display:inline-block;margin-top:8px;color:var(--good);font-size:10px;font-weight:800;text-decoration:none}.source-link:hover{text-decoration:underline}.contact-box{margin-top:10px;padding:12px;border:1px solid #303030;border-radius:12px;background:#050505}.contact-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:8px}.contact-email{font-size:12px;font-weight:900;color:#fff;overflow-wrap:anywhere}.action-btn{display:inline-block;border:1px solid var(--good);background:#050505;color:var(--good);border-radius:999px;padding:7px 10px;font-size:9px;font-weight:1000;letter-spacing:.07em;text-decoration:none;cursor:pointer}.action-btn.primary{background:var(--good);color:#000}.verified-badge{display:inline-block;margin-left:6px;color:var(--good);font-size:9px;font-weight:1000;letter-spacing:.08em}.reject-note{color:var(--muted);font-size:10px;margin-top:8px}.proof-box{margin-top:10px;padding:10px;border:1px solid var(--line);border-radius:12px;background:#030303}.proof-head{display:flex;justify-content:space-between;gap:8px;align-items:center}.proof-good{color:var(--good);font-weight:1000;font-size:9px;letter-spacing:.1em}.proof-warn{color:var(--warn);font-weight:1000;font-size:9px;letter-spacing:.1em}.proof-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}.proof-item{font-size:9px;color:var(--muted);line-height:1.35;overflow-wrap:anywhere}.proof-item b{display:block;color:#fff;font-size:10px;margin-top:2px}.integrity{margin-bottom:14px;padding:14px;border:1px solid #2b2b2b;border-radius:14px;background:#050505}.worker-engine{margin-bottom:14px;padding:14px;border:1px solid #2b2b2b;border-radius:14px;background:#050505}.worker-engine-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-top:10px}.worker-engine-grid>div{padding:10px;border:1px solid var(--line);border-radius:11px;background:#030303}.worker-engine-grid b{display:block;margin-top:3px}.run-workers{border:1px solid var(--good);background:var(--good);color:#000;border-radius:999px;padding:9px 13px;font-size:10px;font-weight:1000;letter-spacing:.08em;cursor:pointer}.run-workers:disabled{opacity:.45}.tool-ok{color:var(--good)}.tool-bad{color:var(--bad)}.integrity b{color:var(--good)}.status.idle{color:var(--warn)}.note{font-size:11px;color:var(--muted);line-height:1.5;margin-top:10px}.bot-face{width:54px;height:54px;border-radius:16px;background:#fff;border:2px solid #fff;color:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;box-shadow:0 0 0 1px #333,0 8px 24px #000}.bot-eyes{display:flex;gap:12px;align-items:center;height:8px}.bot-eye{width:6px;height:6px;border-radius:50%;background:#000}.bot-mouth{width:20px;height:8px;border-bottom:3px solid #000;border-radius:0 0 18px 18px}.bot-face.serious .bot-mouth{height:0;border-radius:0;border-bottom-width:2px}.bot-face.focus .bot-eye:first-child{height:3px;border-radius:4px}.bot-face.focus .bot-mouth{width:14px}.bot-face.idea .bot-mouth{width:8px;height:8px;border:2px solid #000;border-radius:50%}.bot-face.scout .bot-eyes{gap:7px}.bot-face.scout .bot-eye{width:8px;height:8px}.bot-face.money .bot-mouth{width:16px;transform:rotate(-4deg)}.bot-face.goal .bot-mouth{width:12px;border-bottom-width:4px}.bot-face.spark .bot-eye:first-child{border-radius:0;transform:rotate(45deg)}.bot-face.chart .bot-mouth{border-bottom:0;border-left:3px solid #000;border-top:3px solid #000;height:8px;border-radius:0;transform:skewY(-20deg)}.agent-top .bot-face{flex:0 0 auto}.topbar{border-bottom:1px solid #1d1d1d;padding-bottom:16px}.live{background:#fff;color:#000;border-color:#fff}.live span{background:#000;box-shadow:none}.tabs button.active,.scan-btn,.run-workers,.action-btn.primary{background:#fff;color:#000;border-color:#fff}.status,.task-label,.fit,.source-link,.proof-good,.integrity b,.scan-live,.post-now b{color:#fff}.action-btn{border-color:#fff;color:#fff}.data-missing,.proof-warn,.status.idle{color:#aaa}@media(max-width:1000px){.platform-grid{grid-template-columns:1fr}.agent-grid{grid-template-columns:repeat(2,1fr)}.span8,.span4,.span6{grid-column:span 12}.decision-grid{grid-template-columns:1fr}.opp{grid-template-columns:1fr 1fr}.meeting-stage{min-height:auto}.meeting-agent,.table-core{position:static;transform:none;width:auto;height:auto;margin:10px 0}.meeting-stage{display:block}}@media(max-width:700px){.worker-engine-grid{grid-template-columns:1fr 1fr}.scanner-grid{grid-template-columns:1fr 1fr}.scanner-stat:last-child{grid-column:span 2}}@media(max-width:600px){.shell{padding:12px}.topbar{align-items:center;gap:10px;margin-bottom:16px}.dtl-mark{width:44px;height:44px}.topbar h1{font-size:22px}.brand-sub{display:none}.live{font-size:8px;padding:8px 9px;letter-spacing:.05em}.platform-grid{gap:10px}.card{border-radius:14px;padding:14px}.agent-grid{grid-template-columns:1fr;gap:10px}.agent{display:block;padding:14px}.agent-top{align-items:center}.opp{grid-template-columns:1fr}.headline{font-size:24px}.tabs{margin:14px 0 12px}.tabs button{padding:9px 12px}.worker-engine-grid{grid-template-columns:1fr 1fr;gap:7px}.proof-grid{grid-template-columns:1fr 1fr}.current-task{margin-top:12px}}\n</style>\n</head>\n<body>\n<div class=\"shell\">\n  <header class=\"topbar\">\n    <div class=\"brand-lockup\"><div class=\"dtl-mark\">DTL</div><div class=\"brand-copy\"><div class=\"eyebrow\">DOWN THE LINE</div><h1>WAR ROOM</h1><div class=\"brand-sub\">CONTENT INTELLIGENCE · GROWTH · OPPORTUNITIES</div></div></div>\n    <div class=\"live\"><span></span> CHECKING WORKERS…</div>\n  </header>\n  <section id=\"platforms\" class=\"platform-grid\"></section>\n  <nav class=\"tabs\" id=\"tabs\">\n    <button class=\"active\" data-view=\"command\">COMMAND</button><button data-view=\"agents\">AGENTS</button><button data-view=\"meeting\">MEETING ROOM</button><button data-view=\"opportunities\">OPPORTUNITIES</button><button data-view=\"gameplan\">GAME PLAN</button><button data-view=\"activity\">ACTIVITY</button>\n  </nav>\n  <main id=\"view\"><section class=\"card\"><div class=\"section-title\">WAR ROOM</div><h2>Loading DTL command center…</h2><p class=\"note\">Connecting to agent state.</p></section></main>\n</div>\n<script>let STATE=null; let current='command';\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[m]));\nconst pct=(v,t)=>v==null?0:Math.max(0,Math.min(100,Math.round(v/t*100)));\nconst proofFresh=a=>{const p=a?.workerProof||{};if(!a?.workerConnected||!p.runId||!p.lastHeartbeatAt||/BLOCKED|FAILED|ERROR/.test(String(p.phase||'')))return false;const t=Date.parse(p.lastHeartbeatAt);return Number.isFinite(t)&&(Date.now()-t)<65*60*1000};\nconst fmtTime=v=>{if(!v)return '—';try{return new Date(v).toLocaleString()}catch(_){return String(v)}};\nasync function load(){\n  try {\n    const r=await fetch('/api/state',{cache:'no-store'});\n    if(!r.ok) throw new Error(`API ${r.status}`);\n    const next=await r.json();\n    if(!next || !Array.isArray(next.platforms) || !Array.isArray(next.agents)) throw new Error('Invalid state payload');\n    STATE=next;\n    renderPlatforms();\n    render();\n    const badge=document.querySelector('.live');\n    if(badge){const n=STATE.agents.filter(proofFresh).length;badge.innerHTML=`<span></span> ${n}/10 VERIFIED WORKERS`;}\n  } catch(err) {\n    console.error('War Room load failed',err);\n    const badge=document.querySelector('.live');\n    if(badge) badge.textContent='WAR ROOM ONLINE · DATA RETRYING';\n    const v=document.querySelector('#view');\n    if(v) v.innerHTML=`<section class=\\\"card\\\"><div class=\\\"section-title\\\">WAR ROOM STATUS</div><h2>Dashboard is online</h2><p class=\\\"note\\\">The live data endpoint is reconnecting. The page will retry automatically.</p><div class=\\\"pitch\\\">${esc(err.message)}</div></section>`;\n  }\n}\nfunction renderPlatforms(){document.querySelector('#platforms').innerHTML=STATE.platforms.map(p=>`<article class=\"card\"><div class=\"platform-head\"><div><div class=\"platform-name\">${esc(p.name)}</div><div class=\"handle\">${esc(p.handle)}</div></div><span class=\"pill\">${esc(p.status)}</span></div><div class=\"big\">${Number(p.followers).toLocaleString()}</div><div class=\"row\"><span class=\"muted\">Followers / subscribers</span><b>${Number(p.followerTarget).toLocaleString()}</b></div><div class=\"progress\"><i style=\"width:${pct(p.followers,p.followerTarget)}%\"></i></div><div class=\"metric\"><div class=\"row\"><span class=\"muted\">${esc(p.metricLabel)}</span><b>${p.metricValue==null?'—':Number(p.metricValue).toLocaleString()} / ${Number(p.metricTarget).toLocaleString()}</b></div><div class=\"progress\"><i style=\"width:${pct(p.metricValue,p.metricTarget)}%\"></i></div>${p.metricValue==null?'<div class=\"data-missing\">DATA NOT CONNECTED</div>':''}<div class=\"note\">${esc(p.note)}</div></div></article>`).join('')}\nfunction botFace(a){const cls={hook:'spark',retention:'focus',content:'idea',packaging:'serious',performance:'chart',discovery:'scout',algorithm:'focus',competitive:'serious',goal:'goal',opportunity:'money'}[a.id]||'';return `<div class=\"bot-face ${cls}\" title=\"${esc(a.name)}\"><div class=\"bot-eyes\"><i class=\"bot-eye\"></i><i class=\"bot-eye\"></i></div><div class=\"bot-mouth\"></div></div>`;}\nfunction agentCards(){return `<div class=\"agent-grid\">${STATE.agents.map(a=>{const verified=proofFresh(a);const p=a.workerProof||{};const type=a.taskType||a.status||'STANDBY';const target=a.targetTitle||a.videoTitle||a.target||a.current||'Awaiting assignment';const targetKind=a.targetKind||((a.videoTitle||a.videoUrl)?'VIDEO':'TARGET');const platform=a.platform||a.targetPlatform||'Cross-platform';const detail=a.currentlyDoing||a.current||'Waiting for the next assignment.';const stamp=a.taskUpdatedAt||a.updatedAt||STATE.meta?.updatedAt||'';const evidence=Array.isArray(p.evidence)?p.evidence.slice(0,3):[];return `<div class=\"agent\"><div class=\"agent-top\">${botFace(a)}<div class=\"agent-id\"><div class=\"status ${verified?'':'idle'}\">${esc(verified?a.status:'IDLE / UNVERIFIED')}</div><h3>${esc(a.name)}</h3><div class=\"muted\">${esc(a.role)}</div></div></div><div class=\"current-task\"><div class=\"task-head\"><span class=\"task-label\">${verified?'CURRENTLY DOING':'WORKER STATE'}</span><span class=\"task-type\">${esc(type)}</span></div><div class=\"task-target\">${esc(targetKind)}: ${esc(target)}</div><div class=\"task-meta\">${esc(platform)}</div><div class=\"task-detail\">${esc(detail)}</div>${stamp?`<div class=\"task-time\">Last task update: ${esc(stamp)}</div>`:''}</div><div class=\"proof-box\"><div class=\"proof-head\"><span class=\"${verified?'proof-good':'proof-warn'}\">${verified?'✓ VERIFIED PROOF OF WORK':'⚠ NO VERIFIED WORKER PROOF'}</span><span class=\"pill\">${esc(p.phase||a.workerMode||'NOT CONNECTED')}</span></div>${verified?`<div class=\"proof-grid\"><div class=\"proof-item\">RUN ID<b>${esc(p.runId||'—')}</b></div><div class=\"proof-item\">LAST HEARTBEAT<b>${esc(fmtTime(p.lastHeartbeatAt))}</b></div><div class=\"proof-item\">SOURCE<b>${esc(p.sourceTitle||p.sourceUrl||'—')}</b></div><div class=\"proof-item\">PROCESSED<b>${esc(p.processedRange||p.pagesProcessed||p.itemsProcessed||'—')}</b></div></div>${p.sourceUrl?`<a class=\"source-link\" href=\"${esc(p.sourceUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">OPEN WORK SOURCE ↗</a>`:''}${evidence.length?`<div class=\"note\">Evidence: ${evidence.map(esc).join(' • ')}</div>`:''}`:`<div class=\"note\">This agent is not allowed to claim Watching, Analyzing, Researching or Tracking until a worker submits a run ID, source and heartbeat/evidence.</div>`}</div><p class=\"finding\">${esc(a.finding)}</p><div class=\"row\"><span class=\"muted\">Confidence</span><b>${a.confidence}%</b></div></div>`}).join('')}</div>`}\nfunction activity(){return STATE.activity.map(x=>`<div class=\"activity-item\"><b>${esc(x.agent)}</b>${esc(x.text)} <span class=\"muted\">· ${esc(x.time)}</span></div>`).join('')}\nfunction command(){const verified=STATE.agents.filter(proofFresh).length;const w=STATE.workerEngine||{},tools=w.tools||{},status=w.status||'STARTING';const last=w.lastCycleAt?fmtTime(w.lastCycleAt):'Not completed yet',next=w.nextCycleAt?fmtTime(w.nextCycleAt):'Starting soon';const src=Array.isArray(w.sourceStatus)?w.sourceStatus.map(x=>`${x.platform}: ${x.items}${x.error?' (blocked)':''}`).join(' · '):'Waiting for source discovery';return `<div class=\"worker-engine\"><div class=\"row\"><div><div class=\"section-title\">REAL WORKER ENGINE</div><b>${esc(status)}</b><div class=\"note\">${esc(w.currentAction||'Preparing autonomous workers…')}</div></div><button class=\"run-workers\" id=\"runWorkers\" ${status==='WORKING'?'disabled':''}>${status==='WORKING'?'WORKING…':'RUN ALL WORKERS NOW'}</button></div><div class=\"worker-engine-grid\"><div><span class=\"muted\">LAST CYCLE</span><b>${esc(last)}</b></div><div><span class=\"muted\">NEXT CYCLE</span><b>${esc(next)}</b></div><div><span class=\"muted\">CYCLES</span><b>${esc(w.cycles??0)}</b></div><div><span class=\"muted\">SOURCES FOUND</span><b>${esc(w.sourcesDiscovered??0)}</b></div><div><span class=\"muted\">TOOLS</span><b><span class=\"${tools.ytDlp?'tool-ok':'tool-bad'}\">yt-dlp ${tools.ytDlp?'✓':'✕'}</span> · <span class=\"${tools.ffmpeg?'tool-ok':'tool-bad'}\">FFmpeg ${tools.ffmpeg?'✓':'✕'}</span></b></div></div><div class=\"note\">${esc(src)}</div>${w.lastError?`<div class=\"note\" style=\"color:var(--warn)\">Last worker error: ${esc(w.lastError)}</div>`:''}</div><div class=\"integrity\"><div class=\"section-title\">SYSTEM INTEGRITY</div><b>${verified}/10 workers currently have fresh successful proof of work.</b><div class=\"note\">Media workers now consume assigned DTL videos continuously from 0:00 through 10:00, or the entire video when shorter, then share that same acquired viewing window across specialists. Proof shows the exact range. If a source blocks Railway, the card reports BLOCKED instead of pretending to work.</div></div><div class=\"grid\"><section class=\"card span8\"><div class=\"section-title\">TEN-AGENT FLOOR</div>${agentCards()}</section><section class=\"card span4\"><div class=\"section-title\">LIVE ACTIVITY</div>${activity()}</section><section class=\"card span6\"><div class=\"section-title\">CURRENT GAME PLAN</div><div class=\"headline\">${esc(STATE.gamePlan.headline)}</div>${STATE.gamePlan.postNow.map(x=>`<div class=\"post-now\"><b>${esc(x.platform)}</b><div class=\"note\">${esc(x.action)}</div></div>`).join('')}</section><section class=\"card span6\"><div class=\"section-title\">MEETING DECISION</div>${decision()}</section></div>`}\nfunction decision(){const d=STATE.meeting.decision;return `<div class=\"decision-grid\">${[['STOP',d.stop],['START',d.start],['KEEP',d.keep],['TEST',d.test],['NOW',d.immediate]].map(x=>`<div class=\"decision\"><b>${x[0]}</b>${esc(x[1])}</div>`).join('')}</div>`}\nfunction meeting(){let pos=[[4,7],[38,2],[72,7],[80,35],[72,68],[38,78],[4,68],[-2,35],[21,19],[58,19]];return `<section class=\"meeting-stage\"><div class=\"table-core\"><div><div class=\"eyebrow\">DTL MEETING ROOM</div><h2>${esc(STATE.meeting.title)}</h2><div class=\"muted\">${esc(STATE.meeting.status)}</div></div></div>${STATE.agents.map((a,i)=>{let msg=STATE.meeting.messages.find(m=>m.agent===a.name);return `<div class=\"meeting-agent\" style=\"left:${pos[i][0]}%;top:${pos[i][1]}%\"><div class=\"avatar\">${esc(a.initials)}</div><b>${esc(a.name)}</b>${msg?`<div class=\"bubble\">${esc(msg.text)}</div>`:''}</div>`}).join('')}</section><section class=\"card\" style=\"margin-top:14px\"><div class=\"section-title\">CIO DECISION</div>${decision()}</section>`}\nfunction opportunities(){const sc=STATE.opportunityScanner||{};const opps=(Array.isArray(STATE.opportunities)?STATE.opportunities:[]).filter(o=>o.verificationLevel==='DIRECT');const status=sc.status||'STARTING';const last=sc.lastScanAt?new Date(sc.lastScanAt).toLocaleString():'Not scanned yet';const next=sc.nextScanAt?new Date(sc.nextScanAt).toLocaleString():'Starting soon';const mailto=o=>o.contactEmail?`mailto:${o.contactEmail}?subject=${encodeURIComponent(o.emailSubject||'Down The Line creator partnership')}&body=${encodeURIComponent(o.emailBody||'')}`:'';return `<section class=\"card\"><div class=\"row\"><div><div class=\"section-title\">REVENUE PIPELINE</div><h2>Opportunity Bot</h2></div><span class=\"pill\">DIRECT OPPORTUNITIES ONLY</span></div><div class=\"scanner\"><div class=\"row\"><div><div class=\"scan-live\">● ${esc(status)}</div><div class=\"note\">${esc(sc.currentAction||'Preparing direct creator opportunity sources…')}</div></div><button class=\"scan-btn\" id=\"scanNow\" ${status==='SCANNING'?'disabled':''}>${status==='SCANNING'?'SCANNING…':'SCAN NOW'}</button></div><div class=\"scanner-grid\"><div class=\"scanner-stat\"><span class=\"muted\">LAST SCAN</span><b>${esc(last)}</b></div><div class=\"scanner-stat\"><span class=\"muted\">NEXT SCAN</span><b>${esc(next)}</b></div><div class=\"scanner-stat\"><span class=\"muted\">PAGES VERIFIED</span><b>${esc(sc.sourcesChecked??0)}</b></div><div class=\"scanner-stat\"><span class=\"muted\">VERIFIED LEADS</span><b>${esc(sc.verifiedLeads??sc.signalsFound??0)}</b></div><div class=\"scanner-stat\"><span class=\"muted\">CONTACT READY</span><b>${esc(sc.contactReady??0)}</b></div><div class=\"scanner-stat\"><span class=\"muted\">ARTICLES REJECTED</span><b>${esc(sc.rejectedArticles??0)}</b></div></div>${sc.lastError?`<div class=\"note\" style=\"color:var(--warn)\">Last source issue: ${esc(sc.lastError)}</div>`:''}<div class=\"reject-note\">News stories, press releases, listicles and pages without a verifiable creator application/contact route are rejected before they reach this pipeline.</div></div>${opps.length?opps.map(o=>{const id=String(o.id||'opp').replace(/[^a-zA-Z0-9_-]/g,'');const ml=mailto(o);return `<div class=\"opp\"><div><h3>${esc(o.brand)} <span class=\"verified-badge\">✓ VERIFIED</span></h3><span class=\"pill\">${esc(o.type)}</span><p class=\"note\">${esc(o.why)}</p><div class=\"contact-box\"><div class=\"muted\">HOW TO START</div><div class=\"contact-email\">${o.contactEmail?esc(o.contactEmail):'No public outreach email found — use the verified application/contact route.'}</div><div class=\"contact-row\">${ml?`<a class=\"action-btn primary\" href=\"${esc(ml)}\">EMAIL NOW ↗</a>`:''}${o.applicationUrl?`<a class=\"action-btn primary\" href=\"${esc(o.applicationUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">APPLY / JOIN ↗</a>`:''}${o.contactUrl&&!o.applicationUrl?`<a class=\"action-btn\" href=\"${esc(o.contactUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">CONTACT PAGE ↗</a>`:''}<button class=\"action-btn copyDraft\" data-draft-id=\"draft-${id}\">COPY PRE-TYPED EMAIL</button></div></div><div class=\"pitch\" id=\"draft-${id}\">SUBJECT: ${esc(o.emailSubject||'Down The Line creator partnership')}\\n\\n${esc(o.emailBody||o.pitch||'')}</div>${o.sourceUrl?`<a class=\"source-link\" href=\"${esc(o.sourceUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\">OPEN VERIFIED PROGRAM PAGE ↗</a>`:''}</div><div><div class=\"muted\">FIT</div><div class=\"fit\">${esc(o.fit)}%</div><div class=\"note\">${esc(o.fitReason||'DTL content fit')}</div></div><div><div class=\"muted\">COMPENSATION / PRODUCT</div><b>${esc(o.compensation)}</b><div class=\"note\">${esc(o.freeProductTerms||o.contact||'Use verified route')}</div></div><div><div class=\"muted\">STATUS</div><span class=\"pill\">${esc(o.status)}</span><div class=\"note\">${esc(o.source)}</div>${o.deadline?`<div class=\"note\">Deadline: ${esc(o.deadline)}</div>`:''}</div></div>`}).join(''):'<div class=\"note\">No directly verified opportunities passed yet. The bot will keep scanning instead of filling this page with news articles.</div>'}</section>`}\nfunction gameplan(){return `<section class=\"card\"><div class=\"section-title\">IF DTL WERE POSTING TODAY</div><div class=\"headline\">${esc(STATE.gamePlan.headline)}</div>${STATE.gamePlan.postNow.map(x=>`<div class=\"post-now\"><b>${esc(x.platform)}</b><p>${esc(x.action)}</p></div>`).join('')}</section>`}\nfunction render(){const v=document.querySelector('#view'); if(current==='command')v.innerHTML=command(); if(current==='agents')v.innerHTML=`<section class=\"card\"><div class=\"section-title\">INDIVIDUAL SPECIALISTS</div>${agentCards()}</section>`; if(current==='meeting')v.innerHTML=meeting(); if(current==='opportunities')v.innerHTML=opportunities(); if(current==='gameplan')v.innerHTML=gameplan(); if(current==='activity')v.innerHTML=`<section class=\"card\"><div class=\"section-title\">ACTIVITY LOG</div>${activity()}</section>`;}\nasync function triggerWorkers(){const b=document.querySelector('#runWorkers');if(b){b.disabled=true;b.textContent='WORKING…'}try{const r=await fetch('/api/workers-run',{method:'POST'});if(!r.ok&&r.status!==202)throw new Error(`Worker API ${r.status}`);await load()}catch(err){console.error(err);if(b){b.disabled=false;b.textContent='RETRY WORKERS'}}}\nasync function triggerOpportunityScan(){const b=document.querySelector('#scanNow');if(b){b.disabled=true;b.textContent='SCANNING…'}try{const r=await fetch('/api/opportunity-scan',{method:'POST'});if(!r.ok)throw new Error(`Scan API ${r.status}`);await load()}catch(err){console.error(err);if(b){b.disabled=false;b.textContent='RETRY SCAN'}}}\ndocument.querySelector('#tabs').addEventListener('click',e=>{if(!e.target.dataset.view)return;current=e.target.dataset.view;document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('active',b===e.target));render()});\ndocument.querySelector('#view').addEventListener('click',async e=>{if(e.target&&e.target.id==='runWorkers')return triggerWorkers();if(e.target&&e.target.id==='scanNow')return triggerOpportunityScan();const b=e.target&&e.target.closest?e.target.closest('.copyDraft'):null;if(b){const el=document.getElementById(b.dataset.draftId);if(!el)return;try{await navigator.clipboard.writeText(el.textContent||'');const t=b.textContent;b.textContent='COPIED ✓';setTimeout(()=>b.textContent=t,1400)}catch(_){b.textContent='SELECT DRAFT BELOW'}}});\nload(); setInterval(load,30000);\n</script>\n</body>\n</html>";
