function opportunityType(text){const x=String(text||'').toLowerCase();if(/free product|complimentary|product sampling|product testing|request the product|voxbox|free store/.test(x))return'FREE PRODUCT / REVIEW';if(/affiliate|commission/.test(x))return'AFFILIATE';if(/ambassador/.test(x))return'AMBASSADOR';if(/sponsor|paid partnership|paid campaign/.test(x))return'PAID / SPONSOR';if(/marketplace|creator campaign|influencer campaign|ugc creator|creator program/.test(x))return'CREATOR CAMPAIGN';return'CREATOR OPPORTUNITY'}
