function runCommand(command, args = [], options = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { cwd: options.cwd || process.cwd(), env: { ...process.env, LC_ALL: 'C' } });
    let stdout = '', stderr = '';
    const max = options.maxOutput || 6 * 1024 * 1024;
    child.stdout.on('data', d => { if (stdout.length < max) stdout += d.toString(); });
    child.stderr.on('data', d => { if (stderr.length < max) stderr += d.toString(); });
    const timer = setTimeout(() => { try { child.kill('SIGKILL'); } catch (_) {} }, options.timeoutMs || 120000);
    child.on('error', err => { clearTimeout(timer); reject(err); });
    child.on('close', code => {
      clearTimeout(timer);
      if (code === 0) return resolve({ stdout, stderr, code });
      const err = new Error(`${command} exited ${code}: ${(stderr || stdout).slice(-1200)}`);
      err.code = code; err.stdout = stdout; err.stderr = stderr; reject(err);
    });
  });
}
