async function runCoreWorkerCycle(trigger='scheduled'){
  if(coreWorkerInFlight)return{ok:true,status:'already-running'};
  coreWorkerInFlight=true;
  let state=applyTaskSchema(await getState());
  const started=new Date();
  try{
    const ybin=ytdlpBin();
    const tools={ytDlp:await commandExists(ybin),ffmpeg:await commandExists('ffmpeg'),ffprobe:await commandExists('ffprobe'),poTokenProvider:fs.existsSync(POT_SCRIPT),cookies:Boolean((process.env.DTL_COOKIES_FILE&&fs.existsSync(process.env.DTL_COOKIES_FILE))||process.env.DTL_YOUTUBE_COOKIES_B64)};
    state.workerEngine={...(state.workerEngine||{}),status:'WORKING',currentAction:'Discovering DTL uploads and assigning real work. One blocked platform will no longer knock every worker offline.',lastStartedAt:started.toISOString(),nextCycleAt:new Date(started.getTime()+CORE_WORKER_INTERVAL_MS).toISOString(),tools,lastError:null};
    recentActivity(state,'SYSTEM',`Started ${trigger} autonomous nine-agent worker cycle.`);
    await saveState(state);
    if(!tools.ytDlp)throw new Error(`yt-dlp is not installed. Expected ${ybin}.`);

    const discovery=await discoverDtlContent();
    const targets=pickTargets(discovery,state);
    state=applyTaskSchema(await getState());
    state.workerEngine.sourcesDiscovered=discovery.reduce((n,x)=>n+(x.entries?.length||0),0);
    state.workerEngine.sourceStatus=discovery.map(x=>({platform:x.source.platform,items:x.entries?.length||0,error:x.error||null,fallback:x.fallback||null}));
    await saveState(state);

    let t1=targets[0]||null,t2=targets[1]||targets[0]||null;
    let prepared1=null,prepared2=null,sameTarget=false;
    if(t1){
      state.workerEngine.currentAction=`Continuously watching/analyzing up to ${secondsToClock(CONTINUOUS_WATCH_SECONDS)} of assigned DTL episodes in order…`;
      await saveState(state);
      prepared1=await safePrepareTarget(t1,CONTINUOUS_WATCH_SECONDS);
      sameTarget=Boolean(t2&&t1.platform===t2.platform&&t1.id===t2.id);
      prepared2=sameTarget?prepared1:(t2?await safePrepareTarget(t2,CONTINUOUS_WATCH_SECONDS):null);
      await runMediaSpecialist(state,'hook',t1,hookResult,'hook/opening-strength analysis',CONTINUOUS_WATCH_SECONDS,prepared1);
      state=applyTaskSchema(await getState());
      await runMediaSpecialist(state,'packaging',t1,packagingResult,'title/opening packaging alignment',CONTINUOUS_WATCH_SECONDS,prepared1);
      state=applyTaskSchema(await getState());
      if(t2)await runMediaSpecialist(state,'retention',t2,retentionResult,'continuous pacing/dead-air/segment-change analysis',CONTINUOUS_WATCH_SECONDS,prepared2);
      state=applyTaskSchema(await getState());
      if(t2)await runMediaSpecialist(state,'content',t2,contentResult,'continuous multi-topic/segment analysis',CONTINUOUS_WATCH_SECONDS,prepared2);
    }else{
      const sourceErr=discovery.map(x=>`${x.source.platform}: ${x.error||'no posts discovered'}`).join(' | ').slice(0,700);
      for(const id of ['hook','packaging','retention','content'])setAgentError(state,id,safeRunId(id),'DTL public video sources',DTL_SOURCES[0].profile,sourceErr||'No public DTL video URLs were discovered this cycle');
      await saveState(state);
    }

    state=applyTaskSchema(await getState());
    const rows=await runPerformanceWorker(state,discovery);
    state=applyTaskSchema(await getState());
    await runDiscoveryWorker(state,rows);
    state=applyTaskSchema(await getState());
    await runAlgorithmWorker(state);
    state=applyTaskSchema(await getState());
    if(t1)await runCompetitiveWorker(state,t1);else setAgentError(state,'competitive',safeRunId('competitive'),'Competitive search seed unavailable',DTL_SOURCES[0].profile,'No current DTL title was available to seed a competitive scan');
    state=applyTaskSchema(await getState());
    await runGoalWorker(state,discovery);

    state=applyTaskSchema(await getState());
    const finished=new Date();
    const recentIds=targets.map(x=>`${x.platform}:${x.id}`).filter(Boolean);
    const blocked=(state.agents||[]).filter(a=>['hook','retention','content','packaging','performance','discovery','algorithm','competitive','goal'].includes(a.id)&&String(a.workerProof?.phase||'').includes('BLOCKED')).length;
    state.workerEngine={...(state.workerEngine||{}),status:blocked?'PARTIAL / SCHEDULED':'SCHEDULED',currentAction:blocked?`${9-blocked}/9 core workers completed or produced usable work; ${blocked} source-dependent worker(s) are retrying without stopping the rest.`:'Nine specialist workers completed this cycle, including continuous ten-minute episode viewing. Waiting for the next scheduled run.',lastCycleAt:finished.toISOString(),nextCycleAt:new Date(finished.getTime()+CORE_WORKER_INTERVAL_MS).toISOString(),cycles:Number(state.workerEngine?.cycles||0)+1,videosProcessed:Number(state.workerEngine?.videosProcessed||0)+(t1?(sameTarget?1:2):0),recentTargetIds:[...recentIds,...(state.workerEngine?.recentTargetIds||[])].slice(0,30),lastError:blocked?`${blocked} worker(s) blocked by source access; other workers continued.`:null};
    recentActivity(state,'SYSTEM',`Nine-agent cycle finished with ${blocked} blocked worker(s); unaffected workers continued.`);
    await saveState(state);
    return{ok:true,partial:Boolean(blocked),blocked,targets:targets.map(x=>({platform:x.platform,title:x.title,url:x.url})),sourcesDiscovered:state.workerEngine.sourcesDiscovered};
  }catch(err){
    state=applyTaskSchema(await getState());
    const now=new Date().toISOString();
    state.workerEngine={...(state.workerEngine||{}),status:'RETRYING',currentAction:'Worker engine hit an internal/tool error. Existing per-worker results are preserved.',lastCycleAt:now,nextCycleAt:new Date(Date.now()+CORE_WORKER_INTERVAL_MS).toISOString(),lastError:String(err.message||err).slice(0,800),cycles:Number(state.workerEngine?.cycles||0)+1};
    recentActivity(state,'SYSTEM',`Worker-engine error recorded without overwriting every agent: ${String(err.message||err).slice(0,300)}`);
    await saveState(state);
    return{ok:false,error:String(err.message||err)};
  }finally{coreWorkerInFlight=false}
}
function startCoreWorkers(){if(coreWorkerTimer)clearInterval(coreWorkerTimer);if(String(process.env.DTL_WORKERS_DISABLED||'').toLowerCase()==='true')return;setTimeout(()=>runCoreWorkerCycle('startup').catch(err=>console.error('Startup worker cycle failed:',err.message)),6500).unref();coreWorkerTimer=setInterval(()=>runCoreWorkerCycle('scheduled').catch(err=>console.error('Scheduled worker cycle failed:',err.message)),CORE_WORKER_INTERVAL_MS);coreWorkerTimer.unref()}

function startOpportunityScanner() {
  if (opportunityScanTimer) clearInterval(opportunityScanTimer);
  setTimeout(() => runOpportunityScan('startup').catch(err => console.error('Startup opportunity scan failed:', err.message)), 2500).unref();
  opportunityScanTimer = setInterval(() => runOpportunityScan('scheduled').catch(err => console.error('Scheduled opportunity scan failed:', err.message)), OPPORTUNITY_SCAN_INTERVAL_MS);
  opportunityScanTimer.unref();
}


app.get('/health', (_req, res) => res.status(200).json({
  ok: true,
  service: 'dtl-war-room',
  database: dbReady ? 'connected' : 'memory-fallback',
  frontend: 'embedded-v12-mobile-monochrome-bot-faces-continuous-workers',
  time: new Date().toISOString()
}));

app.get('/api/state', async (_req, res) => {
  try {
    res.set('Cache-Control', 'no-store');
    res.json(await getState());
  } catch (err) {
    console.error('State endpoint failed:', err);
    res.status(500).json({ error: 'Unable to load War Room state', detail: err.message });
  }
});

app.post('/api/ingest', async (req, res) => {
  if (!authorized(req)) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const state = await getState();
    const event = req.body || {};
    for (const key of ['platforms','agents','meeting','gamePlan','opportunities','verdicts','analytics']) {
      if (event[key] !== undefined) state[key] = event[key];
    }
    if (event.activity) state.activity = [...event.activity, ...(state.activity || [])].slice(0, 100);
    res.json({ ok: true, state: await saveState(state) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/agents/:id', async (req, res) => {
  if (!authorized(req)) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const state = await getState();
    const id = String(req.params.id || '').toLowerCase();
    const index = (state.agents || []).findIndex(a => String(a.id).toLowerCase() === id);
    if (index < 0) return res.status(404).json({ error: 'Agent not found' });
    const patch = req.body || {};
    let updated = { ...state.agents[index], ...patch, id: state.agents[index].id, taskUpdatedAt: new Date().toISOString() };
    if (updated.id !== 'opportunity' && !hasWorkerProof(updated)) {
      updated = { ...updated, status: 'IDLE', workerConnected: false, workerMode: 'NO WORKER CONNECTED', taskType: 'NO VERIFIED WORKER', targetKind: 'WORKER', targetTitle: 'No verified source processing', currentlyDoing: 'Task text may be assigned, but the dashboard will not claim active work until verified worker proof is submitted to /api/workers/:id/proof.' };
    }
    state.agents[index] = updated;
    state.activity = [{ time: 'Now', agent: updated.name, text: `Current task updated: ${updated.targetTitle || updated.videoTitle || updated.current || 'assignment changed'}` }, ...(state.activity || [])].slice(0, 100);
    await saveState(state);
    res.json({ ok: true, agent: updated });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/workers/:id/proof', async (req, res) => {
  if (!authorized(req)) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const state = await getState();
    const id = String(req.params.id || '').toLowerCase();
    const index = (state.agents || []).findIndex(a => String(a.id).toLowerCase() === id);
    if (index < 0) return res.status(404).json({ error: 'Agent not found' });
    const body = req.body || {};
    const proof = body.workerProof || body.proof || body;
    if (!proof.runId || !proof.lastHeartbeatAt || !(proof.sourceUrl || proof.sourceTitle)) {
      return res.status(400).json({ error: 'Proof requires runId, lastHeartbeatAt, and sourceUrl or sourceTitle. Cosmetic status updates are not accepted as proof.' });
    }
    const evidence = Array.isArray(proof.evidence) ? proof.evidence.filter(Boolean).map(String).slice(0,20) : [];
    if (!evidence.length && !proof.processedRange && !proof.itemsProcessed && !proof.pagesProcessed) {
      return res.status(400).json({ error: 'Proof requires evidence or a processed range/count.' });
    }
    const agent = state.agents[index];
    const phase = String(proof.phase || body.phase || 'WORKING').toUpperCase();
    const status = /COMPLETE|DONE/.test(phase) ? 'Completed' : 'Working';
    state.agents[index] = {
      ...agent,
      ...(body.agentPatch && typeof body.agentPatch === 'object' ? body.agentPatch : {}),
      id: agent.id,
      status,
      workerConnected: true,
      workerMode: body.workerMode || 'VERIFIED EXTERNAL WORKER',
      workerProof: { ...proof, evidence, phase, receivedAt: new Date().toISOString() },
      taskUpdatedAt: new Date().toISOString()
    };
    state.activity = [{ time: 'Now', agent: agent.name, text: `Verified worker proof received for run ${proof.runId}: ${proof.sourceTitle || proof.sourceUrl}` }, ...(state.activity || [])].slice(0,100);
    await saveState(state);
    res.json({ ok: true, agent: state.agents[index] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/workers-run', async (_req, res) => {
  try {
    if (coreWorkerInFlight) return res.status(202).json({ ok: true, status: 'already-running' });
    const result = await runCoreWorkerCycle('manual');
    res.status(result.ok ? 200 : 502).json(result);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.post('/api/opportunity-scan', async (_req, res) => {
  try {
    if (opportunityScanInFlight) return res.status(202).json({ ok: true, status: 'already-scanning' });
    const result = await runOpportunityScan('manual');
    res.status(result.ok ? 200 : 502).json(result);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/opportunities', async (req, res) => {
  if (!authorized(req)) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const state = await getState();
    const body = req.body || {};
    const item = { ...body, id: body.id || `opp-${Date.now()}`, createdAt: new Date().toISOString() };
    state.opportunities = [item, ...(state.opportunities || []).filter(x => x.id !== 'seed-1')];
    state.activity = [{ time: 'Now', agent: 'OPPORTUNITY', text: `New opportunity: ${item.brand || 'Unnamed lead'}` }, ...(state.activity || [])].slice(0, 100);
    await saveState(state);
    res.json({ ok: true, item });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Frontend is embedded in this file so Railway cannot fail because a /public folder was missed during upload.
app.use((req, res, next) => {
  if (req.method !== 'GET') return next();
  res.status(200).type('html').send(PAGE);
});

app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Server error' });
});

server = app.listen(PORT, HOST, () => {
  console.log(`DTL War Room listening on http://${HOST}:${PORT}`);
  tryInitDb().finally(() => { startOpportunityScanner(); startCoreWorkers(); });
});

async function shutdown(signal) {
  console.log(`${signal} received; shutting down cleanly`);
  if (opportunityScanTimer) clearInterval(opportunityScanTimer);
  if (coreWorkerTimer) clearInterval(coreWorkerTimer);
  if (server) server.close(async () => {
    try { if (pool) await pool.end(); } catch (_) {}
    process.exit(0);
  });
  setTimeout(() => process.exit(0), 5000).unref();
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
